import java.util.*;

public class Main {
    static long factorial(int n) {
        return n <= 1 ? 1 : n * factorial(n - 1);
    }

    public static void main(String[] args) {
        System.out.println(factorial(new Scanner(System.in).nextInt()));
    }
}

